// v1.41.0 CARD 312 - CREDENTIAL EXPIRY IS REPORTED IN-BAND.
// The lapse itself was always handled correctly: lookupToken's SELECT refuses an expired
// row, so the seat simply stops resolving. What was missing was NOTICE - nothing told a
// session that the credential it had just authenticated with was days from lapsing, so the
// first signal anyone got was the outage. This reads the expires_at that lookupToken now
// carries back. It never reads, renews, extends, mints or returns a token value, and it
// changes no authentication or authorization decision.
var SESSION_EXPIRY_WARN_DAYS = 14;
function sessionCredentialStatus(s) {
  var raw = String((s && s.expires_at) || "").trim();
  var tokenId = (s && s.token_id) || null;
  if (!raw) {
    return {
      token_id: tokenId,
      expires_at: "",
      days_remaining: null,
      state: "no_expiry",
      note: "This credential carries no expiry - an env-bound credential, or a stored row whose expires_at is unset. Nothing to renew and nothing to warn about."
    };
  }
  var ms = Date.parse(raw.indexOf("T") === -1 ? raw.replace(" ", "T") + "Z" : raw);
  if (!isFinite(ms)) {
    return {
      token_id: tokenId,
      expires_at: raw,
      days_remaining: null,
      state: "unreadable",
      note: "expires_at is stored but could not be parsed, so no countdown is reported rather than a guessed one."
    };
  }
  var days = Math.floor((ms - Date.now()) / 86400000);
  var state = days <= SESSION_EXPIRY_WARN_DAYS ? "expiring_soon" : "ok";
  return {
    token_id: tokenId,
    expires_at: raw,
    days_remaining: days,
    state: state,
    note: state === "expiring_soon"
      ? "This credential lapses in " + days + " day(s). Renewal is a MINT plus a PASTE, never an edit of the existing row: mint a replacement, copy the plaintext once from /relay/token, and paste it into the calling client's key field. The current credential stays valid until it lapses on its own."
      : "Credential is current. Renewal, when it comes, is a mint plus a paste - the existing row is never edited."
  };
}

